 var dollar=trim.indexOf('$'),left=dollar>=0?trim.slice(0,dollar):trim,directive=dollar>=0?trim.slice(dollar+1).trim():'';var hash=left.indexOf('#'),endpointText=hash>=0?left.slice(0,hash).trim():left,remark=hash>=0?left.slice(hash+1).trim():'';var endpoint=parseEndpoint(endpointText);
 if(!endpoint)return{kind:'invalid',raw:value,index:index,remark:remark,directive:directive};
