function loadLocal(){try{var value=JSON.parse(localStorage.getItem(STORE_KEY)||'{}');return value&&typeof value==='object'?value:{}}catch(error){return{}}}
function typeName(meta){var type=String(meta&&meta.type||'').toLowerCase();if(type==='isp'||meta&&meta.mobile)return{label:'住宅/ISP',className:'residential'};if(type==='hosting')return{label:'机房',className:'hosting'};if(type==='business')return{label:'商用',className:'business'};return{label:meta&&meta.status==='pending'?'检测中':'未检测',className:meta&&meta.status==='pending'?'pending':''}}
