function syncText(shouldMark){if(!tool||!tool.textarea)return;tool.textarea.value=tool.lines.join('\n');lastTextareaValue=tool.textarea.value;if(typeof tool.textarea._refreshLineEditor==='function')tool.textarea._refreshLineEditor();tool.textarea.dispatchEvent(new Event('input',{bubbles:true}));if(shouldMark)mark();render();persistLocal()}
function reloadLines(force){if(!tool||!tool.textarea)return;var value=String(tool.textarea.value||'');if(!force&&value===lastTextareaValue)return;if(value==='正在加载...')return;lastTextareaValue=value;tool.lines=value.split(/\r?\n/);render()}
function clearSelection(){tool.selected={};render()}
function selectVisible(){visibleItems().forEach(function(item){if(item.kind==='entry')tool.selected[item.index]=true});render()}
function moveEntry(index,direction){var slots=tool.lines.map(function(x,i){return parseLine(x,i)}).filter(function(x){return x.kind==='entry'}).map(function(x){return x.index}),pos=slots.indexOf(index),target=pos+direction;if(pos<0||target<0||target>=slots.length)return;var other=slots[target],tmp=tool.lines[index];tool.lines[index]=tool.lines[other];tool.lines[other]=tmp;syncText(true);tool.selected[index]=true}
function removeSelected(){var indexes=selectedIndexes().sort(function(a,b){return b-a});if(!indexes.length){toast('请先选择要删除的行','error');return}if(!confirm('确认删除已选择的 '+indexes.length+' 行？'))return;indexes.forEach(function(i){tool.lines.splice(i,1)});clearSelection();syncText(true);toast('已删除 '+indexes.length+' 行','success')}
