function applyBulk(){var indexes=selectedIndexes(),prefix=String(el('chainToolPrefix')&&el('chainToolPrefix').value||''),suffix=String(el('chainToolSuffix')&&el('chainToolSuffix').value||''),host=String(el('chainToolHost')&&el('chainToolHost').value||'').trim(),port=String(el('chainToolPort')&&el('chainToolPort').value||'').trim(),protocol=String(el('chainToolChainProtocol')&&el('chainToolChainProtocol').value||'').trim(),address=String(el('chainToolChainAddress')&&el('chainToolChainAddress').value||'').trim();if(!indexes.length){toast('请先选择要批量修改的行','error');return}if(port&&(!/^\d{1,5}$/.test(port)||Number(port)<1||Number(port)>65535)){toast('批量端口必须是 1~65535','error');return}indexes.forEach(function(index){var item=parseLine(tool.lines[index],index);if(item.kind!=='entry')return;if(host){var parsed=parseEndpoint(host+(port?':'+port:''));if(!parsed){toast('批量主机格式无效','error');return}item.host=parsed.host;item.port=parsed.port;item.endpoint=parsed.endpoint}else if(port){item.port=port;item.endpoint=item.host+':'+port}if(prefix||suffix)item.remark=prefix+item.remark+suffix;if(protocol&&address)item.directive=protocol+'://'+address;tool.lines[index]=formatLine(item)});syncText(true);toast('已批量修改 '+indexes.length+' 行','success')}
function sortEntries(){var sort=String(el('chainToolSort')&&el('chainToolSort').value||'original'),slots=tool.lines.map(function(x,i){return parseLine(x,i)}).filter(function(x){return x.kind==='entry'}),sorted=slots.slice();sorted.sort(function(a,b){if(sort==='endpoint')return a.endpoint.localeCompare(b.endpoint);if(sort==='remark')return String(a.remark||'').localeCompare(String(b.remark||''));if(sort==='latency'){var am=metaFor(a),bm=metaFor(b),av=Number(am&&am.latency),bv=Number(bm&&bm.latency);return(Number.isFinite(av)?av:999999)-(Number.isFinite(bv)?bv:999999)}return a.index-b.index});slots.forEach(function(item,i){tool.lines[item.index]=formatLine(sorted[i])});syncText(true);toast('已按当前排序应用到原文','success')}
function autoName(){var indexes=selectedIndexes();if(!indexes.length)indexes=tool.lines.map(function(x,i){return i}).filter(function(i){return parseLine(tool.lines[i],i).kind==='entry'});if(!indexes.length){toast('没有可命名的节点','error');return}indexes.forEach(function(index){var item=parseLine(tool.lines[index],index);if(item.kind!=='entry')return;var meta=metaFor(item),kind=typeName(meta).label,parts=[meta&&meta.country||'',kind,meta&&meta.latency?meta.latency+'ms':''].filter(Boolean),base=String(item.remark||item.endpoint).replace(/^(?:\[[^\]]+\]\s*)+/,'').trim();item.remark='['+parts.join(' ')+'] '+base;tool.lines[index]=formatLine(item)});syncText(true);toast('已自动命名 '+indexes.length+' 个节点','success')}
function entryText(){return tool.lines.join('\n')}
function decodeBytesB64(value){var binary=atob(value),bytes=new Uint8Array(binary.length);for(var i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return bytes}
