function download(name,content,type){var blob=new Blob([content],{type:type||'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1000)}
function exportFile(mode){var text=entryText(),stamp=new Date().toISOString().replace(/[:.]/g,'-');if(mode==='plain')download('chain-preferred-'+stamp+'.txt',text);else if(mode==='json')download('chain-preferred-'+stamp+'.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),checksum:checksum(text),text:text,sources:tool.sources,meta:tool.meta},null,2),'application/json;charset=utf-8');else{var key=String(el('chainToolMaskKey')&&el('chainToolMaskKey').value||tool.maskKey||'edge-tunnel-chain-v1');tool.maskKey=key;persistLocal();download('chain-preferred-'+stamp+'.obf','EDGE_CHAIN_OBFUSCATED_V1\n'+checksum(text)+'\n'+maskText(text,key),'text/plain;charset=utf-8')}toast('文件已导出','success')}
