function importText(text,mode){var incoming=parseImport(text),old=entryText();if(mode==='merge'){var existing={};tool.lines.forEach(function(raw,i){var item=parseLine(raw,i);if(item.kind==='entry')existing[keyFor(item)]=true});incoming.split(/\r?\n/).forEach(function(raw){var item=parseLine(raw,0);if(item.kind==='entry'&&!existing[keyFor(item)]){tool.lines.push(raw);existing[keyFor(item)]=true}})}else tool.lines=incoming.split(/\r?\n/);syncText(true);toast(mode==='merge'?'已合并导入节点':'已替换为导入内容','success')}
function chooseImport(mode){var file=el('chainToolFile');file.dataset.mode=mode;file.value='';file.click()}
function loadSources(){var area=el('chainToolSources');if(area)area.value=(tool.sources||[]).join('\n')}
function readSources(){var area=el('chainToolSources');tool.sources=String(area&&area.value||'').split(/\r?\n/).map(function(x){return x.trim()}).filter(Boolean).slice(0,16);persistLocal()}
function mergeSourceText(text){var incoming='';try{var parsed=JSON.parse(text);if(Array.isArray(parsed))incoming=parsed.join('\n');else if(parsed&&Array.isArray(parsed.data))incoming=parsed.data.join('\n');else if(parsed&&typeof parsed.text==='string')incoming=parsed.text}catch(error){incoming=text}var existing={};tool.lines.forEach(function(raw,i){var item=parseLine(raw,i);if(item.kind==='entry')existing[keyFor(item)]=true});incoming.split(/\r?\n/).forEach(function(raw){var item=parseLine(raw,0);if(item.kind==='entry'&&!existing[keyFor(item)]){tool.lines.push(raw);existing[keyFor(item)]=true}})}
async function refreshSources(){readSources();if(!tool.sources.length){toast('请先填写至少一个来源地址','error');return}var button=el('chainToolRefresh');if(button)button.disabled=true;try{var response=await fetch('/admin/chain/fetch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({urls:tool.sources})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'来源刷新失败');var added=0;data.results.forEach(function(result){if(result.ok){var before=tool.lines.length;mergeSourceText(result.text);added+=tool.lines.length-before}});syncText(true);var failures=data.results.filter(function(x){return !x.ok});toast('来源刷新完成，新增 '+added+' 行'+(failures.length?'，失败 '+failures.length+' 个':''),failures.length?'info':'success');}catch(error){toast('来源刷新失败: '+error.message,'error')}finally{if(button)button.disabled=false}}
function applyAutoRefresh(){if(refreshTimer)clearInterval(refreshTimer);refreshTimer=null;var enabled=!!tool.settings.refreshEnabled,minutes=Math.max(5,Number(tool.settings.refreshMinutes)||60);if(enabled)refreshTimer=setInterval(refreshSources,minutes*60*1000)}
function saveSettings(){tool.settings.refreshEnabled=!!(el('chainToolAutoRefresh')&&el('chainToolAutoRefresh').checked);tool.settings.refreshMinutes=Number(el('chainToolRefreshMinutes')&&el('chainToolRefreshMinutes').value)||60;tool.maskKey=String(el('chainToolMaskKey')&&el('chainToolMaskKey').value||'edge-tunnel-chain-v1');persistLocal();applyAutoRefresh()}
