async function loadWorkspace(){try{var local=loadLocal();tool.sources=Array.isArray(local.sources)?local.sources:[];tool.settings=Object.assign(tool.settings,local.settings||{});tool.meta=local.meta&&typeof local.meta==='object'?local.meta:{};tool.maskKey=String(local.maskKey||tool.maskKey);var response=await fetch('/admin/chain/state?_t='+Date.now(),{cache:'no-store'}),data=await response.json();if(response.ok&&data&&data.version){if(Array.isArray(data.sources)&&data.sources.length)tool.sources=data.sources;tool.settings=Object.assign(tool.settings,data.settings||{});tool.meta=Object.assign(tool.meta,data.meta||{});if(!String(tool.textarea.value||'').trim()&&String(data.text||'').trim())tool.textarea.value=data.text;lastTextareaValue=null;reloadLines(true);persistLocal()}loadSources();if(el('chainToolAutoRefresh'))el('chainToolAutoRefresh').checked=!!tool.settings.refreshEnabled;if(el('chainToolRefreshMinutes'))el('chainToolRefreshMinutes').value=String(tool.settings.refreshMinutes||60);if(el('chainToolMaskKey'))el('chainToolMaskKey').value=tool.maskKey;applyAutoRefresh();render()}catch(error){loadSources();if(el('chainToolAutoRefresh'))el('chainToolAutoRefresh').checked=!!tool.settings.refreshEnabled;if(el('chainToolRefreshMinutes'))el('chainToolRefreshMinutes').value=String(tool.settings.refreshMinutes||60);if(el('chainToolMaskKey'))el('chainToolMaskKey').value=tool.maskKey;applyAutoRefresh()}}
async function loadBackups(){try{var response=await fetch('/admin/chain/backups?_t='+Date.now(),{cache:'no-store'}),data=await response.json(),select=el('chainToolBackupSelect');if(!select)return;select.innerHTML='<option value="">选择备份</option>';(data.backups||[]).forEach(function(item){var option=document.createElement('option');option.value=item.id;option.textContent=item.name+' · '+new Date(item.createdAt).toLocaleString()+' · '+item.entryCount+'行';select.appendChild(option)})}catch(error){}}
async function loadAudit(){try{var response=await fetch('/admin/chain/audit?_t='+Date.now(),{cache:'no-store'}),data=await response.json(),target=el('chainToolAuditList');if(!target)return;target.textContent=(data.audit||[]).slice(0,5).map(function(item){return new Date(item.time).toLocaleString()+' · '+item.action+' · '+JSON.stringify(item.details||{})}).join('\n')||'暂无工具箱操作日志'}catch(error){}}
