function hostToIp(host){var clean=String(host||'').replace(/^\[|\]$/g,'');if(/^(?:\d{1,3}\.){3}\d{1,3}$/.test(clean)||clean.indexOf(':')>=0)return Promise.resolve(clean);return fetch('https://dns.google/resolve?name='+encodeURIComponent(clean)+'&type=A',{cache:'no-store'}).then(function(r){return r.json()}).then(function(data){var answer=(data.Answer||[]).find(function(x){return x.type===1&&x.data});if(!answer)throw new Error('域名没有 A 记录');return answer.data})}
async function inspectOne(item){var host=item.host;var ip=await hostToIp(host),info;if(typeof window.fetchIpInfoByIp==='function')info=await window.fetchIpInfoByIp(ip);else{var response=await fetch('https://api.090227.xyz/api/ipsb?ip='+encodeURIComponent(ip),{cache:'no-store'});if(!response.ok)throw new Error('IP 信息接口 HTTP '+response.status);info=await response.json()}var company=info.company||{},asn=info.asn||{},type=String(company.type||asn.type||info.company_type||info.asn_type||info.type||'').toLowerCase(),country=String(info.location&&info.location.country_code||info.country_code||info.cc||'').trim(),asnName=String(asn.org||info.asn_organization||info.organization||info.as_name||'').trim(),asnValue=String(asn.asn||info.asn||info.asn_num||'').trim();return{type:type,ip:String(info.ip||ip),country:country,asn:asnValue,organization:asnName,mobile:!!(info.is_mobile||info.mobile||info.isMobile),status:'info',checkedAt:new Date().toISOString()}}
async function inspectIndexes(indexes){var items=indexes.map(function(i){return parseLine(tool.lines[i],i)}).filter(function(x){return x.kind==='entry'});if(!items.length){toast('没有可检测的节点','error');return}var button=el('chainToolInspect');if(button)button.disabled=true;var cursor=0,worker=async function(){while(cursor<items.length){var item=items[cursor++];tool.meta[keyFor(item)]={status:'pending',checkedAt:new Date().toISOString()};render();try{tool.meta[keyFor(item)]=await inspectOne(item)}catch(error){tool.meta[keyFor(item)]={type:'',status:'error',organization:error.message,checkedAt:new Date().toISOString()}}render()}};try{await Promise.all(Array.from({length:Math.min(4,items.length)},worker));persistLocal();toast('IP 类型检测完成','success')}finally{if(button)button.disabled=false}}
